from pathlib import Path
import subprocess
r=Path.home()/'bplus-drop';t=Path('/tmp/share112');t.mkdir(exist_ok=True)
# Lightweight Android value-object doubles exercise the actual builder without claiming OS behavior.
for name,code in {
'android/net/Uri.java':'package android.net;public class Uri{String s;private Uri(String s){this.s=s;}public static Uri parse(String s){return new Uri(s);}public String getScheme(){return s.split(":")[0];}}',
'android/content/ClipData.java':'package android.content;import android.net.Uri;public class ClipData{int n=1;public static class Item{public Item(Uri u){}}public static ClipData newRawUri(String s,Uri u){return new ClipData();}public void addItem(Item i){n++;}public int getItemCount(){return n;}}',
'android/content/Intent.java':'package android.content;import java.util.*;import android.net.Uri;public class Intent{public static final String ACTION_SEND="send",ACTION_SEND_MULTIPLE="multiple",EXTRA_STREAM="stream";public static final int FLAG_GRANT_READ_URI_PERMISSION=1;public String action,type;public Object stream;public int flags;public ClipData clip;public Intent(String a){action=a;}public void setType(String t){type=t;}public void putExtra(String k,Uri u){stream=u;}public void putParcelableArrayListExtra(String k,ArrayList<Uri> u){stream=u;}public void setClipData(ClipData c){clip=c;}public void addFlags(int f){flags|=f;}}'}.items():
 p=t/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(code)
(t/'Tests.java').write_text('''import com.bplus.share.*;import android.content.*;import android.net.Uri;import java.util.*;public class Tests{static int n;static void ok(boolean b,String s)throws Exception{if(!b)throw new Exception(s);n++;System.out.println("PASS "+s);}public static void main(String[]a)throws Exception{ok(ShareRules.mime(Arrays.asList("image/jpeg","image/jpeg")).equals("image/jpeg"),"same MIME retained");ok(ShareRules.mime(Arrays.asList("image/jpeg","image/png")).equals("image/*"),"mixed images use image wildcard");ok(ShareRules.mime(Arrays.asList("image/jpeg","application/pdf")).equals("*/*"),"mixed categories use wildcard");ArrayList<Uri> u=new ArrayList<>();u.add(Uri.parse("content://first/1"));Intent i=ShareIntents.build(u,"image/jpeg");ok(i.action.equals(Intent.ACTION_SEND)&&i.clip.getItemCount()==1&&i.flags==1,"single share has stream, ClipData and read grant");u.add(Uri.parse("content://second/2"));i=ShareIntents.build(u,"*/*");ok(i.action.equals(Intent.ACTION_SEND_MULTIPLE)&&((ArrayList)i.stream).size()==2&&i.clip.getItemCount()==2&&i.flags==1,"multiple share includes every URI and read grant");boolean no=false;try{ShareIntents.build(new ArrayList<>(),"*/*");}catch(IllegalArgumentException e){no=true;}ok(no,"empty batch refused");no=false;u.add(Uri.parse("file:///private"));try{ShareIntents.build(u,"*/*");}catch(IllegalArgumentException e){no=true;}ok(no,"file URI refused");System.out.println(n+" assertions. JVM Android doubles, not actual chooser/WhatsApp behavior.");}}''')
